  const crate = (x, y, w, h) => `<g transform="translate(${f(x)},${f(y)})"><rect x="${-w / 2}" y="${-h}" width="${w}" height="${h}" fill="url(#jkv_wood)"/><rect x="${-w / 2}" y="${-h}" width="${w}" height="${h}" fill="url(#jkv_lit)" opacity=".7"/><rect x="${-w / 2}" y="${-h}" width="${w}" height="${h}" fill="none" stroke="#4a2c16" stroke-width="5"/><path d="M${-w / 2 + 3},${-h + 3}L${w / 2 - 3},-3M${w / 2 - 3},${-h + 3}L${-w / 2 + 3},-3" stroke="#4a2c16" stroke-width="4"/>${nail(-w / 2 + 7, -h + 7, 2.4)}${nail(w / 2 - 7, -h + 7, 2.4)}${nail(-w / 2 + 7, -7, 2.4)}${nail(w / 2 - 7, -7, 2.4)}</g>`;
