  const tuft = (x, y, s = 1, r) => `<g transform="translate(${f(x)},${f(y)}) scale(${s})">${[-14, -8, -2, 4, 10, 15].map((dx, k) => `<path d="M${dx},0q${dx * 0.4},-14 ${dx * 0.9 + (k % 2 ? 4 : -3)},-${22 + r() * 14}" stroke="${k % 2 ? "#6a9a48" : "#4a7a3a"}" stroke-width="3" stroke-linecap="round" fill="none"/>`).join("")}</g>`;
