      // the hills' ridge: trees along it, paler than the hills (far things are paler)
      const ridge = [[-2400, 1150], [-1500, 880], [-800, 1040], [0, 860], [900, 1060], [1700, 880], [2600, 1060], [3800, 920]];
      const yAt = (x) => { for (let k = 0; k + 1 < ridge.length; k++) { const [x0, y0] = ridge[k], [x1, y1] = ridge[k + 1]; if (x >= x0 && x <= x1) return y0 + (y1 - y0) * (x - x0) / (x1 - x0); } return 1000; };
      h += `<g opacity=".85">`;
