        [[w * 0.18, 0], [w * 0.6, 1]].forEach(([wx, k]) => { const ww = w * 0.22, wh = h * 0.2, cx = wx + ww / 2, cy = -h * 0.72 + wh / 2;
          s += `<rect x="${f(wx)}" y="${f(-h * 0.72)}" width="${f(ww)}" height="${f(wh)}" fill="url(#${lit ? "jkv_glassLit" : "jkv_glassDay"})"/>${lit ? `<rect x="${f(wx - 10)}" y="${f(-h * 0.72 - 10)}" width="${f(ww + 20)}" height="${f(wh + 20)}" rx="8" fill="#ffd890" opacity=".22"/>` : ""}
            <path d="M${f(cx)},${f(-h * 0.72)}V${f(-h * 0.72 + wh)}M${f(wx)},${f(cy)}H${f(wx + ww)}" stroke="#4a3220" stroke-width="3"/><rect x="${f(wx)}" y="${f(-h * 0.72)}" width="${f(ww)}" height="${f(wh)}" fill="none" stroke="#5a3a24" stroke-width="5"/><path d="M${f(wx - 6)},${f(-h * 0.72 - 8)}H${f(wx + ww + 6)}" stroke="#6a4a2c" stroke-width="7"/><path d="M${f(wx - 8)},${f(-h * 0.72 + wh + 5)}H${f(wx + ww + 8)}" stroke="#8a6a44" stroke-width="6"/>
            ${[-1, 1].map((d) => `<rect x="${f(d < 0 ? wx - 18 : wx + ww + 4)}" y="${f(-h * 0.72 - 2)}" width="14" height="${f(wh + 4)}" rx="2" fill="#4d6a62"/><rect x="${f(d < 0 ? wx - 18 : wx + ww + 4)}" y="${f(-h * 0.72 - 2)}" width="14" height="${f(wh + 4)}" rx="2" fill="url(#jkv_litV)" opacity=".6"/>`).join("")}
            ${k === 0 ? `<rect x="${f(wx - 4)}" y="${f(-h * 0.72 + wh + 10)}" width="${f(ww + 8)}" height="12" rx="2" fill="#6a4a2a"/>${[0.2, 0.5, 0.8].map((t, j) => `<circle cx="${f(wx + ww * t)}" cy="${f(-h * 0.72 + wh + 6)}" r="5" fill="${["#d8443a", "#f6d36a", "#ff8ab0"][j]}"/>`).join("")}` : ""}`; });
        // the door: planks, a step, a knocker; one house gets a hanging shop sign (a loaf)
